-- ============================================================================
-- Guia do Vendedor — seed de FONTES e IMAGENS
-- Gerado em 2026-08-03 a partir da auditoria do guia.html antigo.
--
-- Nenhuma imagem nasce 'verificada': o schema exige autor + licença +
-- verificada_em + aprovada_por, e ainda não existe aprovador nomeado na
-- Branorte. Todas entram 'pendente' (aparecem com selo) ou 'reprovada' (não
-- aparecem — a UI cai no fallback).
-- ============================================================================

on conflict (chave) do update set titulo = excluded.titulo, organizacao = excluded.organizacao, tipo = excluded.tipo, observacao = excluded.observacao;

on conflict (slug) do update set arquivo_url = excluded.arquivo_url, alt = excluded.alt, legenda = excluded.legenda, autor = excluded.autor, licenca = excluded.licenca, fonte_url = excluded.fonte_url, url_original = excluded.url_original, status = excluded.status, identifica_item = excluded.identifica_item, verificada_em = excluded.verificada_em, aprovada_por = excluded.aprovada_por, motivo_reprovacao = excluded.motivo_reprovacao;
