insert into public.guia_fontes (chave, titulo, organizacao, tipo, observacao) values
  ('embrapa-suinos-aves', 'Embrapa Suínos e Aves — publicações técnicas', 'Embrapa Suínos e Aves (Concórdia/SC)', 'embrapa', 'Edição e URL específicas a confirmar por publicação citada.'),
  ('embrapa-gado-corte', 'Embrapa Gado de Corte — publicações técnicas', 'Embrapa Gado de Corte (Campo Grande/MS)', 'embrapa', 'Edição e URL específicas a confirmar por publicação citada.'),
  ('embrapa-gado-leite', 'Embrapa Gado de Leite — publicações técnicas', 'Embrapa Gado de Leite (Juiz de Fora/MG)', 'embrapa', 'Edição e URL específicas a confirmar por publicação citada.'),
  ('embrapa-caprinos-ovinos', 'Embrapa Caprinos e Ovinos — publicações técnicas', 'Embrapa Caprinos e Ovinos (Sobral/CE)', 'embrapa', 'Edição e URL específicas a confirmar por publicação citada.'),
  ('embrapa-semiarido', 'Embrapa Semiárido — palma forrageira e convivência com a seca', 'Embrapa Semiárido (Petrolina/PE)', 'embrapa', 'Edição e URL específicas a confirmar.'),
  ('rostagno-tabelas', 'Tabelas Brasileiras para Aves e Suínos — composição de alimentos e exigências nutricionais', 'UFV — Rostagno, H. S. et al.', 'literatura', 'REFERÊNCIA PRINCIPAL de composição e inclusão. Edição e ano a confirmar com o nutricionista antes de publicar qualquer faixa como fechada.'),
  ('mapa-alimentacao-animal', 'Legislação de produtos destinados à alimentação animal', 'MAPA — Ministério da Agricultura e Pecuária', 'legislacao', 'Instruções normativas aplicáveis a fabricação, rotulagem, aditivos e boas práticas. Número da IN a confirmar por assunto.'),
  ('abcz', 'Padrões raciais das raças zebuínas', 'ABCZ — Associação Brasileira dos Criadores de Zebu', 'associacao_raca', 'Fonte oficial para Nelore, Guzerá, Brahman, Gir, Tabapuã.'),
  ('girolando', 'Padrão racial e graus de sangue do Girolando', 'Associação Brasileira dos Criadores de Girolando', 'associacao_raca', 'Necessária para fechar a definição de grau de sangue e a participação do Girolando na produção nacional.'),
  ('abccan', 'Padrão racial do Canchim', 'ABCCAN — Associação Brasileira dos Criadores de Canchim', 'associacao_raca', null),
  ('abcb-angus', 'Padrão racial e programas de carne Angus', 'Associação Brasileira de Angus', 'associacao_raca', null),
  ('manual-cobb', 'Manual de manejo e objetivos de desempenho — Cobb', 'Cobb-Vantress', 'manual_linhagem', 'OBRIGATÓRIO: qualquer número de conversão precisa citar edição, ano, sexo, idade e peso-alvo. Os valores do guia antigo (1,97/2,16 + "no campo 1,5") eram contraditórios e foram removidos.'),
  ('manual-ross', 'Broiler Performance Objectives / Manual de manejo — Ross', 'Aviagen', 'manual_linhagem', 'OBRIGATÓRIO: edição, ano, sexo, idade e peso-alvo. Os valores do guia antigo (1,89/2,01) estavam sem contexto e foram removidos.'),
  ('manual-hyline', 'Commercial Layer Management Guide — Hy-Line Brown / W-36', 'Hy-Line International', 'manual_linhagem', 'Ovos por ave alojada e consumo dependem da idade final considerada. Sem isso o número não vale.'),
  ('manual-isa', 'Product Guide — ISA Brown', 'ISA / Hendrix Genetics', 'manual_linhagem', null),
  ('manual-lohmann', 'Layer Management Guide — Lohmann Brown / LSL', 'Lohmann Breeders (EW Group)', 'manual_linhagem', null),
  ('branorte-catalogo', 'Catálogo de equipamentos e capacidades da linha Branorte', 'Branorte', 'branorte', 'Base do bloco "o que a Branorte atende". Conferido no catálogo do CRM (precos_branorte / orcamento_modelos) em 03/08/2026: 0 itens de peletização ou extrusão. Linha Compacta JR 30 kg/h a Compacta 03 500 kg/h.'),
  ('branorte-engenharia', 'Engenharia Branorte — comportamento de materiais no equipamento', 'Branorte', 'branorte', 'PENDENTE. Densidade, abrasividade, formação de ponte, corrosão e misturador indicado precisam do aval da engenharia. Os valores atuais são inferência de literatura e prática, não medição.')
