  ('mestica-pasto', '/img/guia/mestica-pasto.webp', 'Vaca mestiça leiteira em pastagem tropical', 'Imagem ilustrativa: representa o tipo/categoria, não serve como prova de identidade racial. Substituir por foto do acervo Branorte quando disponível.', 'Fernando Gabriel de Melo Domingo', 'CC BY-SA 4.0', 'https://commons.wikimedia.org/', null, 'pendente', false, null, null, null),
  ('isa-brown', '/img/guia/isa-brown.webp', 'Galinha poedeira de plumagem marrom em galpão comercial', 'Linhagens comerciais de aves não são visualmente distinguíveis entre si: Cobb e Ross são ambos frangos brancos de corte; ISA, Hy-Line e Lohmann Brown são todas poedeiras de plumagem marrom. Nenhuma foto — nem a oficial da genética — permite verificar a identidade. Esta imagem ilustra o TIPO de ave, não a linhagem.', 'Mercoaves', 'CC BY-SA 4.0', 'https://commons.wikimedia.org/', null, 'pendente', false, null, null, null),
  ('lohmann-brown', '/img/guia/lohmann-brown.webp', 'Galinha poedeira de plumagem marrom-clara', 'Linhagens comerciais de aves não são visualmente distinguíveis entre si: Cobb e Ross são ambos frangos brancos de corte; ISA, Hy-Line e Lohmann Brown são todas poedeiras de plumagem marrom. Nenhuma foto — nem a oficial da genética — permite verificar a identidade. Esta imagem ilustra o TIPO de ave, não a linhagem.', 'Konstantin Nikiforov', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/', null, 'pendente', false, null, null, null),
  ('white-leghorn', '/img/guia/white-leghorn.webp', 'Galinha de plumagem branca e crista vermelha simples, tipo leve de postura', 'Linhagens comerciais de aves não são visualmente distinguíveis entre si: Cobb e Ross são ambos frangos brancos de corte; ISA, Hy-Line e Lohmann Brown são todas poedeiras de plumagem marrom. Nenhuma foto — nem a oficial da genética — permite verificar a identidade. Esta imagem ilustra o TIPO de ave, não a linhagem.', 'Bodlina', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/', null, 'pendente', false, null, null, null),
  ('pescoco-pelado', '/img/guia/pescoco-pelado.webp', 'Galo caipira de pescoço nu, criado a campo', 'Linhagens comerciais de aves não são visualmente distinguíveis entre si: Cobb e Ross são ambos frangos brancos de corte; ISA, Hy-Line e Lohmann Brown são todas poedeiras de plumagem marrom. Nenhuma foto — nem a oficial da genética — permite verificar a identidade. Esta imagem ilustra o TIPO de ave, não a linhagem.', 'Trigueiro martins', 'CC BY-SA 4.0', 'https://commons.wikimedia.org/', null, 'pendente', false, null, null, null),
  ('paraiso-pedres', '/img/guia/paraiso-pedres.webp', 'Galinha de plumagem pedrês criada em sistema a campo', 'Linhagens comerciais de aves não são visualmente distinguíveis entre si: Cobb e Ross são ambos frangos brancos de corte; ISA, Hy-Line e Lohmann Brown são todas poedeiras de plumagem marrom. Nenhuma foto — nem a oficial da genética — permite verificar a identidade. Esta imagem ilustra o TIPO de ave, não a linhagem.', 'Thomas Kriese', 'CC BY 2.0', 'https://commons.wikimedia.org/', null, 'pendente', false, null, null, null),
