  ('large-white', '/img/guia/large-white.webp', 'Suíno branco com orelhas eretas e pernil cheio', null, 'Homoatrox', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/', null, 'pendente', true, null, null, null),
