  ('calcario-calcitico', '/img/guia/calcario-calcitico.webp', 'Rocha calcária moída', 'Imagem ilustrativa: representa o tipo/categoria, não serve como prova de identidade racial. Substituir por foto do acervo Branorte quando disponível.', 'Slknight', 'CC BY-SA 4.0', 'https://commons.wikimedia.org/', null, 'pendente', false, null, null, null),
