  ('silagem-milho', '/img/guia/silagem-milho.webp', 'Silagem armazenada em silo de superfície', 'Imagem ilustrativa: representa o tipo/categoria, não serve como prova de identidade racial. Substituir por foto do acervo Branorte quando disponível.', 'B. Grochowski', 'Domínio público', 'https://commons.wikimedia.org/', null, 'pendente', false, null, null, null),
  ('palma-forrageira', '/img/guia/palma-forrageira.webp', 'Plantio de palma forrageira (cacto Opuntia) no semiárido', null, 'YG01', 'CC BY 4.0', 'https://commons.wikimedia.org/', null, 'pendente', true, null, null, null),
  ('embrapa-051', null, 'Embrapa 051 (poedeira colonial) — sem foto verificada', null, null, null, null, null, 'reprovada', false, null, null, 'Foto genérica de galinha vermelha com pintinhos brancos, em pastagem. Não identifica a linhagem e a coloração dos pintinhos é incoerente com a genética descrita no card.'),
  ('embrapa-021', null, 'Embrapa 021 (frango de corte de crescimento lento) — sem foto verificada', null, null, null, null, null, 'reprovada', false, null, null, 'A foto mostra uma galinha adulta em gramado; o card trata de FRANGO DE CORTE. Item errado, além de genérica.'),
  ('cobb-500', null, 'Cobb 500 — sem foto verificada', null, null, null, null, null, 'reprovada', false, null, null, 'Foto genérica de frangos em galpão, creditada a "Animals Uncovered" — organização de ativismo animal. Impróprio para material comercial da Branorte, além de não identificar a linhagem.'),
  ('ross-308', null, 'Ross 308 — sem foto verificada', null, null, null, null, null, 'reprovada', false, null, null, 'Galinha branca isolada sobre tábua de madeira, em contexto de criação de fundo de quintal. Não representa granja industrial nem identifica a linhagem.'),
  ('hy-line-brown', null, 'Hy-Line Brown / W-36 — sem foto verificada', null, null, null, null, null, 'reprovada', false, null, null, 'Ave jovem dentro de caixa de papelão. Qualidade editorial inaceitável e não identifica a linhagem.'),
  ('concentrado-proteico', null, 'Concentrado proteico — sem foto verificada', null, null, null, null, null, 'reprovada', false, null, null, 'GRAVE: mostra ração PELETIZADA (processo que a Branorte não realiza) e é foto de marketing da RICHI Machinery, fabricante de peletizadoras — concorrente de equipamento.'),
  ('torta-dende', null, 'Torta de dendê — sem foto verificada', null, null, null, null, null, 'reprovada', false, null, null, 'Mostra frutos frescos de dendê, não a torta (coproduto) que entra na ração.'),
  ('brangus', null, 'Brangus — sem foto verificada', null, null, null, null, null, 'reprovada', false, null, null, 'Slide antigo escaneado, amarelado e de baixa resolução. O animal não evidencia a fração zebuína (sem cupim), ficando indistinguível de Angus puro.')
